package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 退赛登记请求。
 *
 * @param bib                 退赛选手参赛号
 * @param status              退赛状态：DNS-未出发，DNF-中途退赛
 * @param reason              退赛原因，非空
 * @param lastCheckpointCode  DNF 最后通过的检查点代码（须为该选手已有分段中顺序最大者）；DNS 不传
 * @param expectedVersion     客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId           全局唯一请求ID（幂等键）
 * @param withdrawalKey       全局唯一退赛登记键（第二层幂等键）
 */
public record RegisterWithdrawalRequest(
        @NotBlank String bib,
        @NotBlank String status,
        @NotBlank String reason,
        String lastCheckpointCode,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId,
        @NotBlank String withdrawalKey
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 撤销退赛请求；退赛键在路径中携带，撤销记录不可变。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RevokeWithdrawalRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.WithdrawalStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 退赛登记响应。
 *
 * @param withdrawalKey      退赛登记键，全局唯一
 * @param bib                退赛选手参赛号
 * @param status             退赛状态：DNS / DNF
 * @param reason             退赛原因
 * @param lastCheckpointCode DNF 最后通过检查点代码；DNS 为 null
 * @param revoked            是否已撤销
 * @param createdAt          登记时间，Unix毫秒时间戳
 * @param revokedAt          撤销时间，Unix毫秒时间戳；未撤销为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record WithdrawalResponse(
        String withdrawalKey,
        String bib,
        WithdrawalStatus status,
        String reason,
        String lastCheckpointCode,
        boolean revoked,
        long createdAt,
        Long revokedAt
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 赛事退赛清单响应（含已撤销记录，按登记时间稳定排列）。
 *
 * @param raceId      赛事ID
 * @param version     查询时的赛事版本号
 * @param withdrawals 全部退赛登记
 */
public record WithdrawalListResponse(
        String raceId,
        int version,
        List<WithdrawalResponse> withdrawals
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.EntryStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 单个选手的参赛状态查询响应。
 *
 * @param raceId              赛事ID
 * @param bib                 参赛号
 * @param version             查询时的赛事版本号
 * @param status              当前参赛状态（RANKED/UNTIMED/MISSING_CHECKPOINT/DISQUALIFIED/DNS/DNF）
 * @param finishTimeMs        原始完赛耗时毫秒；计时缺失为 null
 * @param lastCheckpointCode  最后通过（顺序最大）的检查点代码；无分段记录为 null
 * @param missingCheckpoints  缺失检查点代码，按检查点顺序排列；无缺失为空列表
 * @param activeWithdrawal    生效中的退赛登记；无退赛或已撤销为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RunnerStatusResponse(
        String raceId,
        String bib,
        int version,
        EntryStatus status,
        Long finishTimeMs,
        String lastCheckpointCode,
        List<String> missingCheckpoints,
        WithdrawalResponse activeWithdrawal
) {
}

